import type { ColDef } from 'ag-grid-community';
import { GanttChartHeader } from 'components/GanttChart/components/GanttChartHeader/GanttChartHeader';
import { merge } from 'lodash';
import { isValidElement } from 'react';

import { ColumnDefsConfig } from '../../Table';
import { TableHeaderType } from '../../types';

interface ColumnDefWithChildren extends ColDef {
  headerComponentParams?: any;
  headerGroupComponentParams?: any;
  children?: ColDef[];
}

const HEADER_TYPES = {
  GANTT: 'gantt',
} as const;

const HEADER_COMPONENTS = {
  [HEADER_TYPES.GANTT]: GanttChartHeader,
} as const;

const applyWidthConstraints = (column: ColumnDefWithChildren): void => {
  if (typeof column.maxWidth === 'number') {
    column.suppressAutoSize = true;
    column.suppressSizeToFit = true;
    return;
  }

  if (typeof column.width === 'number' && typeof column.minWidth === 'number') {
    column.flex = 0;
    column.suppressSizeToFit = true;
  }
};

const HEADER_JSX_TOOLTIP_SENTINEL = ' ';

const applyJsxHeaderTooltip = (
  column: ColumnDefWithChildren,
  headerTooltip: Exclude<ColumnDefsConfig[string]['headerTooltip'], string>,
): void => {
  const resolveHeaderTooltipContent = () => headerTooltip;

  column.headerTooltip = HEADER_JSX_TOOLTIP_SENTINEL;
  column.headerComponentParams = {
    ...column.headerComponentParams,
    headerTooltipContent: resolveHeaderTooltipContent,
  };
  column.headerGroupComponentParams = {
    ...column.headerGroupComponentParams,
    headerTooltipContent: resolveHeaderTooltipContent,
  };
};

const applyColumnConfig = (
  column: ColumnDefWithChildren,
  config: ColumnDefsConfig[string],
): void => {
  const { headerTooltip, ...configWithoutTooltip } = config;

  merge(column, configWithoutTooltip);

  if (headerTooltip === undefined) {
    return;
  }

  if (isValidElement(headerTooltip)) {
    applyJsxHeaderTooltip(column, headerTooltip);
    return;
  }

  if (typeof headerTooltip === 'string') {
    column.headerTooltip = headerTooltip;
  }
};

const applyHeaderWidthOverrides = (
  column: ColumnDefWithChildren,
  header: TableHeaderType,
): void => {
  if (typeof header.width === 'number') {
    column.width = header.width;
    column.flex = 0;
  }

  if (typeof header.maxWidth === 'number') {
    column.maxWidth = header.maxWidth;
  }

  if (typeof header.minWidth === 'number') {
    column.minWidth = Math.max(column.minWidth ?? 0, header.minWidth);
  }
};

const generateColumns = (
  headers: TableHeaderType[],
  configs: ColumnDefsConfig | undefined,
) => {
  return headers.map((header) => {
    const configHeaderTooltip = configs?.[header.title]?.headerTooltip;
    const params = {
      subtitle: header.subtitle,
      imgName: header.imgName,
      dataTestId: header.dataTestId, //header.dataTestId,
      ...(typeof configHeaderTooltip === 'string'
        ? { headerTooltip: configHeaderTooltip }
        : {}),
      ...header.params,
    };
    const column: ColumnDefWithChildren = {
      headerName: header.title,
      field: header.id,
      headerComponentParams: params,
      headerGroupComponentParams: params,
      ...(header.minWidth ? { minWidth: header.minWidth } : null),
    };
    if (params?.type === HEADER_TYPES.GANTT) {
      column.headerComponent = HEADER_COMPONENTS[HEADER_TYPES.GANTT];
      column.headerComponentParams = {
        ...params?.data,
        merge: false,
        tooltip: params?.headerTooltip,
      };
    }

    if (header.id || header.title) {
      const config =
        configs?.[header.id] ||
        configs?.[header.title] ||
        configs?.[header.id?.split('_')[0] + '_'];

      if (config) {
        applyColumnConfig(column, config);
      }
    }

    if (header.children && header.children.length > 0) {
      column.children = generateColumns(header.children, configs);
    }

    applyHeaderWidthOverrides(column, header);
    applyWidthConstraints(column);

    return column;
  });
};

export const generateColumnDefs = (
  data: TableHeaderType[],
  configs: ColumnDefsConfig | undefined,
) => {
  return generateColumns(data, configs);
};
